-- Tahap 5.4–5.5: events, attendance and atomic journals.
SET LOCAL ROLE sim_guru_owner;
CREATE TABLE app.event_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),type text NOT NULL CHECK(type IN('rutin','insidental')),days int[] NOT NULL,dates date[] NOT NULL,time_start time NOT NULL,time_end time NOT NULL,jtm int NOT NULL CHECK(jtm BETWEEN 1 AND 99),description text NOT NULL CHECK(length(description)<=1000),date_start date NOT NULL,date_end date NOT NULL,active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK(time_end>time_start),CHECK(date_end-date_start BETWEEN 0 AND 365),CHECK((type='rutin' AND cardinality(days)>0 AND cardinality(dates)=0 AND days<@ARRAY[0,1,2,3,4,5,6]) OR(type='insidental' AND cardinality(dates)>0 AND cardinality(days)=0)));
CREATE UNIQUE INDEX event_name ON app.event_definitions(lower(name)) WHERE active;
CREATE TABLE app.event_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES app.event_definitions(id),date date NOT NULL,user_id uuid NOT NULL REFERENCES app.app_users(id),time_in time NOT NULL,recorded_by uuid NOT NULL REFERENCES app.app_users(id),cancelled_at timestamptz,version bigint NOT NULL DEFAULT 1,snapshot_jtm numeric(12,4),UNIQUE(event_id,date,user_id));
CREATE INDEX event_attendance_owner ON app.event_attendance(user_id,date);
CREATE TABLE app.event_journals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attendance_id uuid NOT NULL UNIQUE REFERENCES app.event_attendance(id),description text NOT NULL CHECK(length(btrim(description)) BETWEEN 1 AND 1000),input_type text NOT NULL CHECK(input_type IN('SAME_DAY','H_MINUS_1')),weight numeric(2,1) NOT NULL CHECK(weight IN(1,0.8)),credited_jtm numeric(12,4) NOT NULL CHECK(credited_jtm>=0),submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(),cancelled_at timestamptz);
CREATE TABLE app.event_journal_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES app.event_definitions(id),date_start date NOT NULL,date_end date NOT NULL,message text NOT NULL CHECK(length(btrim(message)) BETWEEN 5 AND 500),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,CHECK(date_end>=date_start));
CREATE INDEX event_block_date ON app.event_journal_blocks(event_id,date_start,date_end) WHERE active;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['app.event_definitions','app.event_attendance','app.event_journals','app.event_journal_blocks'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY owner_internal ON %s TO sim_guru_owner USING(true) WITH CHECK(true)',t);EXECUTE format('REVOKE ALL ON %s FROM PUBLIC,sim_guru_business,sim_guru_auth,sim_guru_worker',t);END LOOP;END $$;
ALTER TABLE app.activity_occurrences DROP CONSTRAINT occurrence_kind,DROP CONSTRAINT occurrence_source;
ALTER TABLE app.activity_occurrences ADD COLUMN event_attendance_id uuid UNIQUE REFERENCES app.event_attendance(id),ADD CONSTRAINT occurrence_kind CHECK(kind IN('KBM','PIKET','UPACARA','EXAM_SUPERVISOR','EXAM_COMMITTEE','EVENT')),
ADD CONSTRAINT occurrence_source CHECK((kind='KBM' AND schedule_id IS NOT NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NULL AND event_attendance_id IS NULL AND class_id IS NOT NULL AND subject_id IS NOT NULL) OR(kind IN('PIKET','UPACARA') AND schedule_id IS NULL AND duty_schedule_id IS NOT NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NULL AND event_attendance_id IS NULL AND class_id IS NULL AND subject_id IS NULL) OR(kind='EXAM_SUPERVISOR' AND schedule_id IS NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NOT NULL AND exam_committee_id IS NULL AND event_attendance_id IS NULL AND class_id IS NULL AND subject_id IS NOT NULL) OR(kind='EXAM_COMMITTEE' AND schedule_id IS NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NOT NULL AND event_attendance_id IS NULL AND class_id IS NULL AND subject_id IS NULL) OR(kind='EVENT' AND schedule_id IS NULL AND duty_schedule_id IS NULL AND exam_supervisor_id IS NULL AND exam_committee_id IS NULL AND event_attendance_id IS NOT NULL AND class_id IS NULL AND subject_id IS NULL));
ALTER TABLE finance.jtm_ledger DROP CONSTRAINT ledger_source_kind;
ALTER TABLE finance.jtm_ledger ADD CONSTRAINT ledger_source_kind CHECK(source_kind IN('KBM','PIKET','UPACARA','EXAM_SUPERVISOR','EXAM_COMMITTEE','EVENT','PARTIAL_SUB_KBM','PARTIAL_SUB_PIKET','PARTIAL_SUB_EXAM','REVERSAL'));
CREATE UNIQUE INDEX ledger_event_revision ON finance.jtm_ledger(assignment_id,revision,source_kind) WHERE source_kind='EVENT';
DO $patch$ DECLARE fn regprocedure:='finance.ledger_integrity()'::regprocedure;b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;IF strpos(b,' IF NEW.source_kind=''KBM'' THEN')=0 THEN RAISE EXCEPTION 'PRIOR_ROUTINE_MISMATCH';END IF;b:=replace(b,' IF NEW.source_kind=''KBM'' THEN',$new$ IF NEW.source_kind='EVENT' THEN
IF o.kind<>'EVENT' OR o.removed_at IS NOT NULL OR NEW.assignment_id IS DISTINCT FROM a.id OR NEW.revision<>a.version OR NEW.user_id<>a.effective_user_id OR NEW.journal_id IS NOT NULL OR NEW.allocation_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM app.event_attendance e JOIN app.event_journals evj ON evj.attendance_id=e.id WHERE e.id=o.event_attendance_id AND e.cancelled_at IS NULL AND evj.cancelled_at IS NULL AND e.user_id=NEW.user_id AND evj.credited_jtm=NEW.jtm AND e.snapshot_jtm=NEW.jtm) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;RETURN NEW;END IF;
 IF NEW.source_kind='KBM' THEN$new$);EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;
CREATE FUNCTION app.event_occurs(p_event uuid,p_date date) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM app.event_definitions WHERE id=p_event AND active AND p_date BETWEEN date_start AND date_end AND((type='rutin' AND extract(dow FROM p_date)::int=ANY(days)) OR(type='insidental' AND p_date=ANY(dates)))) $$;
CREATE FUNCTION app.event_operator(p_user uuid,p_date date) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT app.actor_is_admin() OR app.is_piket(p_user,p_date) OR app.is_committee(p_user,p_date,NULL,true) $$;
CREATE FUNCTION app.event_save(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;d jsonb:=p_data->'data';rid uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid());old app.event_definitions%ROWTYPE;n app.event_definitions%ROWTYPE;ds date[];days int[];day date;BEGIN actor:=app.activity_guard(p_session,true);PERFORM auth_private.require_admin();SELECT * INTO old FROM app.event_definitions WHERE id=rid FOR UPDATE;
IF coalesce(old.version,0) IS DISTINCT FROM(p_data->>'version')::bigint OR(old.id IS NOT NULL AND NOT old.active) THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
IF length(btrim(coalesce(p_data->>'reason',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;

SELECT coalesce(array_agg(value::date),ARRAY[]::date[]) INTO ds FROM jsonb_array_elements_text(d->'dates');SELECT coalesce(array_agg(value::int),ARRAY[]::int[]) INTO days FROM jsonb_array_elements_text(d->'days');
IF((d->>'dateStart')::date<app.activity_today() AND(old.id IS NULL OR(d->>'dateStart')::date IS DISTINCT FROM old.date_start)) OR EXISTS(SELECT 1 FROM unnest(ds) x WHERE x NOT BETWEEN(d->>'dateStart')::date AND(d->>'dateEnd')::date) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF EXISTS(SELECT 1 FROM app.event_attendance a WHERE a.event_id=rid AND(a.date NOT BETWEEN(d->>'dateStart')::date AND(d->>'dateEnd')::date OR a.time_in<(d->>'timeStart')::time OR a.time_in>=(d->>'timeEnd')::time OR NOT((d->>'type'='rutin' AND extract(dow FROM a.date)::int=ANY(days)) OR(d->>'type'='insidental' AND a.date=ANY(ds))))) THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
FOR day IN SELECT DISTINCT a.date FROM app.event_attendance a WHERE event_id=rid LOOP PERFORM finance.guard_open(day);END LOOP;
INSERT INTO app.event_definitions(id,name,type,days,dates,time_start,time_end,jtm,description,date_start,date_end) VALUES(rid,btrim(d->>'name'),d->>'type',days,ds,(d->>'timeStart')::time,(d->>'timeEnd')::time,(d->>'jtm')::int,d->>'description',(d->>'dateStart')::date,(d->>'dateEnd')::date) ON CONFLICT(id) DO UPDATE SET name=excluded.name,type=excluded.type,days=excluded.days,dates=excluded.dates,time_start=excluded.time_start,time_end=excluded.time_end,jtm=excluded.jtm,description=excluded.description,date_start=excluded.date_start,date_end=excluded.date_end,version=app.event_definitions.version+1 RETURNING * INTO n;
UPDATE app.activity_occurrences o SET time_start=n.time_start,time_end=n.time_end,scheduled_jtm=n.jtm WHERE o.event_attendance_id IN(SELECT a.id FROM app.event_attendance a WHERE a.event_id=rid AND NOT EXISTS(SELECT 1 FROM app.event_journals j WHERE j.attendance_id=a.id));
PERFORM app.activity_audit('event-save',rid,p_data->>'reason',to_jsonb(old),to_jsonb(n));RETURN to_jsonb(n)||jsonb_build_object('version',n.version::text);END $$;
CREATE FUNCTION app.event_attendance_command(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;e app.event_definitions%ROWTYPE;a app.event_attendance%ROWTYPE;day date;uid uuid;oid uuid;old jsonb;BEGIN actor:=app.activity_guard(p_session,true);IF length(btrim(coalesce(p_data->>'reason',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF p_data->>'operation'='attend' THEN day:=(p_data->>'date')::date;uid:=(p_data->>'userId')::uuid;SELECT * INTO e FROM app.event_definitions WHERE id=(p_data->>'eventId')::uuid;IF day IS DISTINCT FROM app.activity_today() OR NOT app.event_operator(actor,day) THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF;
IF NOT app.event_occurs(e.id,day) OR NOT EXISTS(SELECT 1 FROM app.app_users WHERE id=uid AND role='guru' AND status='active') OR(p_data->>'timeIn')::time<e.time_start OR(p_data->>'timeIn')::time>=e.time_end OR p_data->>'timeIn' IS NULL THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;PERFORM finance.guard_open(day);
SELECT * INTO a FROM app.event_attendance WHERE event_id=e.id AND date=day AND user_id=uid FOR UPDATE;old:=to_jsonb(a);IF a.id IS NOT NULL THEN IF a.cancelled_at IS NULL OR EXISTS(SELECT 1 FROM app.event_journals WHERE attendance_id=a.id) THEN RAISE EXCEPTION 'DUPLICATE_JOURNAL' USING ERRCODE='23505';END IF;
UPDATE app.event_attendance SET cancelled_at=NULL,time_in=(p_data->>'timeIn')::time,recorded_by=actor,version=version+1 WHERE id=a.id RETURNING * INTO a;UPDATE app.activity_occurrences SET removed_at=NULL WHERE event_attendance_id=a.id;
ELSE INSERT INTO app.event_attendance(event_id,date,user_id,time_in,recorded_by) VALUES(e.id,day,uid,(p_data->>'timeIn')::time,actor) RETURNING * INTO a;
INSERT INTO app.activity_occurrences(kind,date,academic_period_id,time_start,time_end,scheduled_jtm,expected_students,snapshot,event_attendance_id) VALUES('EVENT',day,(app.day_context_internal(day)->>'academicPeriodId')::uuid,e.time_start,e.time_end,e.jtm,0,jsonb_build_object('eventName',e.name,'teacherName',(SELECT full_name FROM app.app_users WHERE id=uid)),a.id) RETURNING id INTO oid;
INSERT INTO app.activity_assignments(occurrence_id,original_user_id,effective_user_id) VALUES(oid,uid,uid);END IF;
ELSIF p_data->>'operation'='cancel' THEN SELECT * INTO a FROM app.event_attendance WHERE id=(p_data->>'attendanceId')::uuid FOR UPDATE;old:=to_jsonb(a);IF a.id IS NULL OR a.cancelled_at IS NOT NULL OR a.date<>app.activity_today() OR NOT app.event_operator(actor,a.date) THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF;
IF a.version IS DISTINCT FROM(p_data->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;PERFORM finance.guard_open(a.date);IF EXISTS(SELECT 1 FROM app.event_journals WHERE attendance_id=a.id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;UPDATE app.event_attendance SET cancelled_at=clock_timestamp(),version=version+1 WHERE id=a.id RETURNING * INTO a;UPDATE app.activity_occurrences SET removed_at=clock_timestamp() WHERE event_attendance_id=a.id;
ELSE RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
PERFORM app.activity_audit('event-attendance',a.id,p_data->>'reason',old,to_jsonb(a));RETURN to_jsonb(a)||jsonb_build_object('version',a.version::text);END $$;
CREATE FUNCTION app.event_journal_save(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;a app.event_attendance%ROWTYPE;e app.event_definitions%ROWTYPE;o app.activity_occurrences%ROWTYPE;x app.activity_assignments%ROWTYPE;j app.event_journals%ROWTYPE;w numeric;credit numeric;BEGIN actor:=app.activity_guard(p_session,true);SELECT * INTO a FROM app.event_attendance WHERE id=(p_data->>'attendanceId')::uuid FOR UPDATE;
IF a.id IS NULL OR a.user_id<>actor OR a.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF a.date>app.activity_today() THEN RAISE EXCEPTION 'FUTURE_DATE' USING ERRCODE='42501';END IF;IF a.date<app.activity_today()-1 THEN RAISE EXCEPTION 'DATE_EXPIRED' USING ERRCODE='42501';END IF;
IF a.date=app.activity_today()-1 AND NOT coalesce((SELECT typed_value='true'::jsonb FROM app.system_settings WHERE key='allow_h_minus_1_journal'),false) THEN RAISE EXCEPTION 'H1_DISABLED' USING ERRCODE='42501';END IF;
IF EXISTS(SELECT 1 FROM app.event_journal_blocks WHERE active AND(event_id IS NULL OR event_id=a.event_id) AND a.date BETWEEN date_start AND date_end) THEN RAISE EXCEPTION 'JOURNAL_BLOCKED' USING ERRCODE='42501';END IF;PERFORM finance.guard_open(a.date);
IF EXISTS(SELECT 1 FROM app.event_journals WHERE attendance_id=a.id) THEN RAISE EXCEPTION 'DUPLICATE_JOURNAL' USING ERRCODE='23505';END IF;IF a.version IS DISTINCT FROM(p_data->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
SELECT * INTO e FROM app.event_definitions WHERE id=a.event_id AND active;IF e.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;w:=CASE WHEN a.date=app.activity_today() THEN 1 ELSE 0.8 END;credit:=round(e.jtm*w,1);
INSERT INTO app.event_journals(attendance_id,description,input_type,weight,credited_jtm) VALUES(a.id,btrim(p_data->>'description'),CASE WHEN w=1 THEN 'SAME_DAY' ELSE 'H_MINUS_1' END,w,credit) RETURNING * INTO j;
UPDATE app.event_attendance SET snapshot_jtm=credit,version=version+1 WHERE id=a.id;SELECT * INTO o FROM app.activity_occurrences WHERE event_attendance_id=a.id;SELECT * INTO x FROM app.activity_assignments WHERE occurrence_id=o.id;
INSERT INTO finance.jtm_ledger(source_kind,occurrence_id,user_id,date,jtm,revision,assignment_id) VALUES('EVENT',o.id,actor,a.date,credit,x.version,x.id);
PERFORM app.activity_audit('event-journal',j.id,'Jurnal acara tersimpan',NULL,to_jsonb(j));RETURN to_jsonb(j);END $$;
CREATE FUNCTION app.event_block_save(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;old app.event_journal_blocks%ROWTYPE;n app.event_journal_blocks%ROWTYPE;rid uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid());BEGIN actor:=app.activity_guard(p_session,true);PERFORM auth_private.require_admin();SELECT * INTO old FROM app.event_journal_blocks WHERE id=rid FOR UPDATE;IF coalesce(old.version,0) IS DISTINCT FROM(p_data->>'version')::bigint THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
INSERT INTO app.event_journal_blocks(id,event_id,date_start,date_end,message,active) VALUES(rid,(p_data->>'eventId')::uuid,(p_data->>'dateStart')::date,(p_data->>'dateEnd')::date,btrim(p_data->>'message'),(p_data->>'active')::boolean) ON CONFLICT(id) DO UPDATE SET event_id=excluded.event_id,date_start=excluded.date_start,date_end=excluded.date_end,message=excluded.message,active=excluded.active,version=app.event_journal_blocks.version+1 RETURNING * INTO n;PERFORM app.activity_audit('event-block',rid,p_data->>'reason',to_jsonb(old),to_jsonb(n));RETURN to_jsonb(n)||jsonb_build_object('version',n.version::text);END $$;
CREATE FUNCTION app.event_fingerprint(p_id uuid) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT md5(jsonb_build_array(to_jsonb(e),(SELECT jsonb_agg(to_jsonb(a) ORDER BY id) FROM app.event_attendance a WHERE event_id=e.id),(SELECT jsonb_agg(to_jsonb(j) ORDER BY j.id) FROM app.event_journals j JOIN app.event_attendance a ON a.id=j.attendance_id WHERE a.event_id=e.id))::text) FROM app.event_definitions e WHERE id=p_id AND active $$;
CREATE FUNCTION app.event_delete(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;v ops.module_previews%ROWTYPE;rid uuid;oid uuid;BEGIN actor:=app.activity_guard(p_session,true);PERFORM auth_private.require_admin();IF p_data->>'previewId' IS NULL THEN rid:=(p_data->>'id')::uuid;IF p_data->>'entity'<>'event' OR app.event_fingerprint(rid) IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;
FOR oid IN SELECT id FROM app.activity_occurrences WHERE event_attendance_id IN(SELECT id FROM app.event_attendance WHERE event_id=rid) LOOP PERFORM finance.guard_open((SELECT date FROM app.activity_occurrences WHERE id=oid));END LOOP;
INSERT INTO ops.module_previews(actor_id,request,fingerprint) VALUES(actor,p_data,app.event_fingerprint(rid)) RETURNING * INTO v;RETURN jsonb_build_object('previewId',v.id,'expiresAt',v.expires_at,'attendance',(SELECT count(*) FROM app.event_attendance WHERE event_id=rid),'journals',(SELECT count(*) FROM app.event_journals j JOIN app.event_attendance a ON a.id=j.attendance_id WHERE a.event_id=rid),'netJtm',coalesce((SELECT sum(jtm) FROM finance.jtm_ledger WHERE occurrence_id IN(SELECT id FROM app.activity_occurrences WHERE event_attendance_id IN(SELECT id FROM app.event_attendance WHERE event_id=rid))),0)::text);END IF;
SELECT * INTO v FROM ops.module_previews WHERE id=(p_data->>'previewId')::uuid FOR UPDATE;rid:=(v.request->>'id')::uuid;IF v.id IS NULL OR v.request->>'entity'<>'event' OR v.actor_id<>actor OR v.consumed_at IS NOT NULL OR v.expires_at<=clock_timestamp() OR p_data->>'confirmed' IS DISTINCT FROM 'true' OR v.fingerprint IS DISTINCT FROM app.event_fingerprint(rid) THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;
FOR oid IN SELECT id FROM app.activity_occurrences WHERE event_attendance_id IN(SELECT id FROM app.event_attendance WHERE event_id=rid) LOOP PERFORM finance.guard_open((SELECT date FROM app.activity_occurrences WHERE id=oid));PERFORM finance.reverse_occurrence(oid);UPDATE app.activity_occurrences SET removed_at=clock_timestamp() WHERE id=oid;END LOOP;
UPDATE app.event_journals SET cancelled_at=clock_timestamp() WHERE attendance_id IN(SELECT id FROM app.event_attendance WHERE event_id=rid) AND cancelled_at IS NULL;UPDATE app.event_attendance SET cancelled_at=coalesce(cancelled_at,clock_timestamp()),version=version+1 WHERE event_id=rid;UPDATE app.event_definitions SET active=false,version=version+1 WHERE id=rid;UPDATE ops.module_previews SET consumed_at=clock_timestamp() WHERE id=v.id;PERFORM app.activity_audit('event-delete',rid,v.request->>'reason',v.request,jsonb_build_object('archived',true));RETURN jsonb_build_object('deleted',true);END $$;
CREATE FUNCTION app.event_read(p_session text,p_filter jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;d date:=(p_filter->>'date')::date;f date:=coalesce((p_filter->>'from')::date,date_trunc('month',(p_filter->>'date')::date)::date);e date:=coalesce((p_filter->>'to')::date,(date_trunc('month',(p_filter->>'date')::date)+interval '1 month - 1 day')::date);operator boolean;BEGIN actor:=app.activity_guard(p_session,false);operator:=app.event_operator(actor,d);IF d IS NULL OR e-f NOT BETWEEN 0 AND 365 THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
RETURN jsonb_build_object('date',d,'canOperate',operator,'events',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('version',version::text) ORDER BY name,id) FROM app.event_definitions x WHERE active),'[]'),'today',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('version',version::text) ORDER BY time_start,id) FROM app.event_definitions x WHERE app.event_occurs(id,d)),'[]'),
'attendance',coalesce((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('version',a.version::text,'teacherName',u.full_name,'eventName',x.name,'journal',j.description,'creditedJtm',coalesce(a.snapshot_jtm,0)::text) ORDER BY a.date DESC,a.time_in DESC,a.id) FROM app.event_attendance a JOIN app.event_definitions x ON x.id=a.event_id JOIN app.app_users u ON u.id=a.user_id LEFT JOIN app.event_journals j ON j.attendance_id=a.id WHERE a.date BETWEEN f AND e AND(app.actor_is_admin() OR a.user_id=actor OR(a.date=d AND operator))),'[]'),
'teachers',CASE WHEN operator THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',full_name) ORDER BY full_name,id) FROM app.app_users WHERE role='guru' AND status='active'),'[]') ELSE '[]'::jsonb END,
'blocks',CASE WHEN app.actor_is_admin() THEN coalesce((SELECT jsonb_agg(to_jsonb(b)||jsonb_build_object('version',version::text) ORDER BY date_start,id) FROM app.event_journal_blocks b),'[]') ELSE '[]'::jsonb END);END $$;
-- Event operations cannot use the exam/duty confirmation entry points.
DO $patch$ DECLARE fn regprocedure:='app.duty_permission(uuid,uuid,text)'::regprocedure;b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,'IF o.kind NOT IN', 'IF o.kind=''EVENT'' THEN RAISE EXCEPTION ''FORBIDDEN'' USING ERRCODE=''42501'';END IF;IF o.kind NOT IN');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;

DO $patch$ DECLARE fn regprocedure:='app.occurrence_command(text,uuid,text,bigint,text)'::regprocedure;b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,' IF o.id IS NULL',' IF o.kind=''EVENT'' THEN RAISE EXCEPTION ''FORBIDDEN'' USING ERRCODE=''42501'';END IF; IF o.id IS NULL');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app,finance FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.event_read(text,jsonb),app.event_save(text,jsonb),app.event_delete(text,jsonb),app.event_attendance_command(text,jsonb),app.event_journal_save(text,jsonb),app.event_block_save(text,jsonb) TO sim_guru_business;
RESET ROLE;
